17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Locale;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Computes the canonical key that identifies an owner's household, namely the pair of last
26	 * name and address. Both fields are compared case-insensitively and with runs of whitespace
27	 * collapsed to a single space, so cosmetic differences do not split a household. Two owners
28	 * belong to the same household exactly when their keys are equal.
29	 */
30	@Component
31	public class HouseholdKey {
32	
33	    /** @return the canonical household key for {@code owner}. */
34	    public String of(Owner owner) {
35	        return of(owner.getLastName(), owner.getAddress());
36	    }
37	
38	    /** @return the canonical household key for the given last name and address. */
39	    public String of(String lastName, String address) {
40	        return normalize(lastName) + "\n" + normalize(address);
41	    }
42	
43	    /** Trim, collapse internal whitespace and lower-case, so equality ignores case and spacing. */
44	    private String normalize(String value) {
45	        if (value == null) {
46	            return "";
47	        }
48	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
49	    }
50	}
