17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.CustomerCodeGenerator;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
41	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
44	import org.springframework.samples.petclinic.rest.validation.HouseholdIdGenerator;
45	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
46	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final OwnerFieldsValidator ownerFieldsValidator;
75	
76	    private final HouseholdDuplicateValidator householdDuplicateValidator;
77	
78	    private final HouseholdIdGenerator householdIdGenerator;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final EmailNormalizer emailNormalizer;
83	
84	    private final CustomerCodeGenerator customerCodeGenerator;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 OwnerFieldsValidator ownerFieldsValidator,
91	                                 HouseholdDuplicateValidator householdDuplicateValidator,
92	                                 HouseholdIdGenerator householdIdGenerator,
93	                                 TelephoneNormalizer telephoneNormalizer,
94	                                 EmailNormalizer emailNormalizer,
95	                                 CustomerCodeGenerator customerCodeGenerator) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	        this.ownerFieldsValidator = ownerFieldsValidator;
101	        this.householdDuplicateValidator = householdDuplicateValidator;
102	        this.householdIdGenerator = householdIdGenerator;
103	        this.telephoneNormalizer = telephoneNormalizer;
104	        this.emailNormalizer = emailNormalizer;
105	        this.customerCodeGenerator = customerCodeGenerator;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingOwnerFieldsException(missingFields);
139	        }
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        applyHouseholdPolicy(owner, ownerFieldsDto);
143	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
144	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
145	            throw new DuplicateTelephoneException(normalizedTelephone);
146	        }
147	        owner.setTelephone(normalizedTelephone);
148	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
149	        if (owner.getRegistrationDate() == null) {
150	            owner.setRegistrationDate(LocalDate.now());
151	        }
152	        owner.setCustomerCode(
153	            customerCodeGenerator.generate(owner.getLastName(), clinicService.countOwners()));
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    /**
162	     * Applies the household rule to an owner about to be created. When the owner shares a
163	     * household (same last name and address, compared case-insensitively with collapsed
164	     * whitespace) with an existing owner, creation is rejected unless the request opted in via
165	     * {@code sharesHousehold}. When it opts in, the new owner and every existing household
166	     * member are stamped with the same stable {@code householdId}.
167	     *
168	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
169	     */
170	    private void applyHouseholdPolicy(Owner owner, OwnerFieldsDto ownerFieldsDto) {
171	        Collection<Owner> sameLastName = this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
172	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
173	        if (members.isEmpty()) {
174	            return;
175	        }
176	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
177	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
178	        }
179	        String householdId = householdIdGenerator.generate(owner);
180	        owner.setHouseholdId(householdId);
181	        for (Owner member : members) {
182	            if (!householdId.equals(member.getHouseholdId())) {
183	                member.setHouseholdId(householdId);
184	                this.clinicService.saveOwner(member);
185	            }
186	        }
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        currentOwner.setAddress(ownerFieldsDto.getAddress());
197	        currentOwner.setCity(ownerFieldsDto.getCity());
198	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
199	        currentOwner.setLastName(ownerFieldsDto.getLastName());
200	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
201	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
202	        this.clinicService.saveOwner(currentOwner);
203	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Transactional
208	    @Override
209	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
210	        Owner owner = this.clinicService.findOwnerById(ownerId);
211	        if (owner == null) {
212	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	        }
214	        this.clinicService.deleteOwner(owner);
215	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner == null) {
223	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	        }
225	        HttpHeaders headers = new HttpHeaders();
226	        Pet pet = petMapper.toPet(petFieldsDto);
227	        owner.setId(ownerId);
228	        pet.setOwner(owner);
229	        pet.getType().setName(null);
230	        this.clinicService.savePet(pet);
231	        PetDto petDto = petMapper.toPetDto(pet);
232	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
233	            .buildAndExpand(pet.getId()).toUri());
234	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
240	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
241	        if (currentOwner != null) {
242	            Pet currentPet = this.clinicService.findPetById(petId);
243	            if (currentPet != null) {
244	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
245	                currentPet.setName(petFieldsDto.getName());
246	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
247	                this.clinicService.savePet(currentPet);
248	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
249	            }
250	        }
251	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
257	        HttpHeaders headers = new HttpHeaders();
258	        Visit visit = visitMapper.toVisit(visitFieldsDto);
259	        Pet pet = new Pet();
260	        pet.setId(petId);
261	        visit.setPet(pet);
262	        this.clinicService.saveVisit(visit);
263	        VisitDto visitDto = visitMapper.toVisitDto(visit);
264	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
265	            .buildAndExpand(visit.getId()).toUri());
266	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
267	    }
268	
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Override
272	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
273	        Owner owner = this.clinicService.findOwnerById(ownerId);
274	        if (owner != null) {
275	            Pet pet = owner.getPet(petId);
276	            if (pet != null) {
277	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
278	            }
279	        }
280	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
281	    }
282	}
