39	        return builder -> builder.addMixIn(OwnerDto.class, OwnerDtoMixin.class);
40	    }
41	
42	    /** Hides the write-only {@code sharesHousehold} hint from serialized {@link OwnerDto} responses. */
43	    abstract static class OwnerDtoMixin {
44	
45	        @JsonProperty(access = JsonProperty.Access.WRITE_ONLY)
46	        abstract Boolean getSharesHousehold();
47	    }
48	}
