18	
19	import java.util.regex.Pattern;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Normalizes a submitted telephone to its canonical stored form in E.164: spaces, dashes
25	 * and brackets are stripped; a leading '+' and country code are kept when present,
26	 * otherwise the default country code '+61' is assumed and a single leading '0' is dropped
27	 * from the national digits. The result must carry 8 to 15 digits after the '+'.
28	 */
29	@Component
30	public class TelephoneNormalizer {
31	
32	    /** Formatting characters removed before interpreting the number. */
33	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
34	
35	    /** Country code assumed when the submitted number carries no leading '+'. */
36	    private static final String DEFAULT_COUNTRY_CODE = "61";
37	
38	    /** The digits following the '+' must number between 8 and 15 inclusive. */
39	    private static final Pattern E164_DIGITS = Pattern.compile("[0-9]{8,15}");
40	
41	    /**
42	     * @param telephone the raw submitted telephone (may be {@code null})
43	     * @return the telephone in E.164 form, i.e. a '+' followed by 8 to 15 digits
44	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
45	     */
46	    public String normalize(String telephone) {
47	        String cleaned = telephone == null ? "" : SEPARATORS.matcher(telephone.trim()).replaceAll("");
48	        String digits = cleaned.startsWith("+") ? cleaned.substring(1) : toDefaultCountry(cleaned);
49	        if (!E164_DIGITS.matcher(digits).matches()) {
50	            throw new InvalidTelephoneException(telephone);
51	        }
52	        return "+" + digits;
53	    }
54	
55	    /**
56	     * Applies the default country code to national digits, dropping a single leading '0'.
57	     */
58	    private String toDefaultCountry(String national) {
59	        String trunkless = national.startsWith("0") ? national.substring(1) : national;
60	        return DEFAULT_COUNTRY_CODE + trunkless;
61	    }
